const D = { fold: 6, density: .55, energy: .62, bloom: .5, speed: 1, scale: 1, hue: 300, x: .5, y: .5, style: 'jewel', seed: 0, alpha: 100, act: 'bloom' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = 6.283185307;
const clp = (v,a,b) => Math.max(a, Math.min(b, v));
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
const st = P.style, ink = (st === 'sumi-ink');
function groundFor(s, hue){
  const h = ((hue%360)+360)%360;
  if (s === 'sumi-ink')       return [36, 10, 90];
  if (s === 'pastel-dream')   return [(h+22)%360, 20, 32];
  if (s === 'neon')           return [(h+200)%360, 72, 5];
  if (s === 'stained-glass')  return [(h+180)%360, 48, 7];
  return [h, 56, 18]; // jewel — deep gem ground
}

// ---- ping-pong feedback buffers (size-keyed) ----
const BW = Math.max(200, Math.min(720, Math.round(width*0.5)));
const BH = Math.max(120, Math.round(BW*height/width));
const fkey = BW+'x'+BH;
if (!S.a || S.fkey !== fkey){
  if (S.a && S.a.remove) S.a.remove(); if (S.b && S.b.remove) S.b.remove();
  S.a = createGraphics(BW, BH); S.a.colorMode(HSB,360,100,100,100);
  S.b = createGraphics(BW, BH); S.b.colorMode(HSB,360,100,100,100);
  S.fkey = fkey; S.seedUsed = null; S.styleUsed = null;
}
// ---- (re)seed emitter brushes + clear buffers on seed/style change ----
if (S.seedUsed !== P.seed || S.styleUsed !== st){
  S.seedUsed = P.seed; S.styleUsed = st;
  S.bp = [];
  for (let i=0;i<8;i++){ S.bp[i] = { pa:fr(i*3+1)*TAU, ra:fr(i*3+2)*TAU, rr1:0.7+fr(i*3+3)*1.6, rr2:0.6+fr(i*7+5)*1.5, hu:fr(i*11+2), sw:0.6+fr(i*13+4) }; }
  const gc0 = groundFor(st, P.hue);
  S.a.push(); S.a.background(gc0[0],gc0[1],gc0[2]); S.a.pop();
  S.b.push(); S.b.background(gc0[0],gc0[1],gc0[2]); S.b.pop();
}

const src = S.a, dst = S.b;
dst.blendMode(BLEND); dst.noStroke();

// ---- N-fold symmetry steps by section (kaleidoscope evolves its order) ----
const secFold = [0, 2, -1, 3, -2, 2, 1, 4];
let N = Math.round(clp(P.fold,3,16)) + secFold[K.section & 7];
N = Math.max(3, Math.min(16, N));
const wedge = TAU / N;
const Ne = Math.min(N, 12); // deposited fold copies (perf cap; visually identical at high N)

const spd = clp(P.speed, 0.2, 3), bl = clp(P.bloom, 0, 1);
const kick = K.pulse*0.5 + A.bass*0.7;
let zoom;
if (P.act === 'implode')     zoom = 1 - (0.003 + bl*0.012)*spd - kick*0.008*bl;
else if (P.act === 'churn')  zoom = 1 + (0.001 + bl*0.004)*spd;
else                         zoom = 1 + (0.004 + bl*0.018)*spd + kick*0.008*bl; // bloom (outward tunnel)
const spin = (0.002 + 0.008*Math.sin(K.t*0.08))*spd + (P.act === 'churn' ? 0.012*spd : 0) + A.lowmid*0.01;
const fade = ink ? 100 : (st === 'neon' ? 91 : st === 'stained-glass' ? 96 : 94);

const cbx = clp(P.x,0,1)*BW, cby = clp(P.y,0,1)*BH;

// ---- feedback pass: spin + zoom + fade the prior frame ----
dst.push();
dst.translate(cbx, cby); dst.rotate(spin); dst.scale(zoom); dst.translate(-cbx, -cby);
if (ink){ dst.image(src, 0, 0, BW, BH); }
else { dst.tint(0,0,fade); dst.image(src, 0, 0, BW, BH); dst.noTint(); }
dst.pop();
// ambient floor / paper dry (keeps luminance up + fills edges on implode)
const gc = groundFor(st, P.hue);
dst.noStroke(); dst.fill(gc[0], gc[1], gc[2], ink ? 6 : 8);
dst.rect(0, 0, BW, BH);

// ---- live emitter: brushes wander a Lissajous inside ONE wedge, folded N ways ----
const ub = Math.min(BW, BH), maxR = Math.max(BW, BH)*0.6;
const nB = 2 + Math.round(clp(P.density,0.1,1)*3);
const hb = (((P.hue + K.section*22 + K.t*1.4) % 360) + 360) % 360;
const dep = 0.55 + P.energy*0.7 + (K.intensity!=null?K.intensity:.6)*0.3 + A.rms*0.5 + kick*0.15;
const dsz = ub*(0.028 + 0.03*P.density)*clp(P.scale,0.5,2)*(0.8 + 0.4*K.swell);

if (ink) dst.blendMode(BLEND);
else if (st === 'stained-glass') dst.blendMode(BLEND);
else if (st === 'pastel-dream') dst.blendMode(SCREEN);
else dst.blendMode(ADD);

for (let b=0;b<nB;b++){
  const bp = S.bp[b];
  const a0 = wedge*(0.5 + 0.5*Math.sin(K.t*(0.10+0.05*spd)*bp.rr1 + bp.pa + b));
  const rn = 0.14 + 0.78*(0.5 + 0.5*Math.sin(K.t*(0.08+0.04*spd)*bp.rr2 + bp.ra));
  const rr = maxR*rn;
  let h = (hb + Math.sin((bp.hu + rn*0.6 + K.t*0.03)*TAU)*70 + rn*40) % 360; h = (h+360)%360;
  let s, v, aOut, aCore;
  if (ink){ h = (26 + bp.hu*22) % 360; s = 12 + rn*18; v = 8 + rn*20; aOut = 10 + P.energy*16; aCore = aOut*0.8; }
  else if (st === 'stained-glass'){ s = 82; v = 52 + rn*32; aOut = Math.min(34, 26 + P.energy*26); aCore = aOut; }
  else if (st === 'pastel-dream'){ s = 26 + rn*22; v = 88 + rn*12; aOut = 16 + P.energy*16; aCore = 22; }
  else if (st === 'neon'){ s = 92 + rn*8; v = 100; aOut = Math.min(30, 9 + dep*10); aCore = 30 + dep*16; }
  else { s = 78 + rn*20; v = 88 + rn*12; aOut = Math.min(30, 12 + dep*10); aCore = 26 + dep*16; } // jewel
  const rBig = dsz*(1.6 + rn*1.1), rCore = dsz*(0.5 + rn*0.3);
  for (let k=0;k<Ne;k++){
    const ab = k*wedge;
    for (let mir=0;mir<2;mir++){
      const ang = mir ? ab - a0 : ab + a0;
      const x = cbx + Math.cos(ang)*rr, y = cby + Math.sin(ang)*rr;
      if (ink){
        dst.fill(h, s, v, aOut); dst.ellipse(x, y, rBig*0.7, rBig*0.5);
        dst.fill(h, s+12, v*0.65, aCore); dst.ellipse(x + (bp.hu-0.5)*rBig*0.25, y + (bp.sw-0.6)*rBig*0.2, rCore, rCore*0.8);
      } else if (st === 'stained-glass'){
        dst.stroke(h, 34, 8, 72); dst.strokeWeight(Math.max(1, ub*0.006));
        dst.fill(h, s, v, aOut); dst.ellipse(x, y, rBig, rBig*0.82); dst.noStroke();
      } else {
        dst.fill(h, s*0.7, v, aOut); dst.ellipse(x, y, rBig, rBig);
        dst.fill(h, s, v, aCore); dst.ellipse(x, y, rCore, rCore);
      }
    }
  }
}
dst.blendMode(BLEND); dst.noStroke();

// ---- composite to screen (upscaled), alpha for VJ compositing ----
push();
if (P.alpha < 100) tint(0,0,100, P.alpha);
image(dst, 0, 0, width, height);
noTint();
pop();

// swap ping-pong
S.a = dst; S.b = src;
blendMode(BLEND); noTint(); drawingContext.shadowBlur = 0;
